def backfill_period_payment(apps, schema_editor):
    """Períodos pagos anteriores al deploy quedaban no revocables
    (period_payment_id NULL): un refund del cobro real no tocaba el acceso.
    Se estampa el último Payment approved cuyo cobro cae dentro de la
    ventana del período vigente (start_date - 2d de margen por skew de
    reloj). Los períodos cortesía (cupón/assign) quedan afuera: su último
    cobro es anterior al start_date del período."""
    Suscription = apps.get_model('suscriptions', 'Suscription')
    Payment = apps.get_model('payments', 'Payment')
    for sus in Suscription.objects.filter(period_payment_id__isnull = True).exclude(end_date__isnull = True):
        if not sus.start_date:
            continue
        window_start = sus.start_date - timedelta(days = 2)
        for payment in Payment.objects.filter(suscription_id = sus.pk, status = 'approved').order_by('-created_at')[:10]:
            effective = payment.paid_at or payment.created_at
            if effective and window_start <= effective <= sus.end_date:
                sus.period_payment_id = payment.pk
                sus.save(update_fields = ['period_payment_id'])
                break


